const body = $input.first().json.body || $input.first().json || {};
const entry = (body.entry && body.entry[0]) || {};

// 1. Detect Reel or Post Comments
if (entry.changes && entry.changes[0] && entry.changes[0].field === 'comments') {
  const cmt = entry.changes[0].value || {};
  const text = cmt.text || '';
  const phoneRegex = /(?:(?:\+?91[\s-]?)?[6-9]\d{9})\b/g;
  const phoneMatch = text.match(phoneRegex);
  const cleanPhone = phoneMatch ? phoneMatch[0].replace(/\D/g, '').slice(-10) : null;

  return [{
    json: {
      eventType: 'comment',
      commentId: cmt.id,
      text: text,
      username: (cmt.from && cmt.from.username) || 'Client',
      phone: cleanPhone,
      hasPhone: Boolean(cleanPhone),
      receivedAt: new Date().toISOString()
    }
  }];
}

// 2. Detect Direct Messages (DMs)
if (entry.messaging && entry.messaging[0]) {
  const msgObj = entry.messaging[0];
  if (msgObj.message && !msgObj.message.is_echo && msgObj.message.text) {
    const text = msgObj.message.text;
    const phoneRegex = /(?:(?:\+?91[\s-]?)?[6-9]\d{9})\b/g;
    const phoneMatch = text.match(phoneRegex);
    const cleanPhone = phoneMatch ? phoneMatch[0].replace(/\D/g, '').slice(-10) : null;

    return [{
      json: {
        eventType: 'dm',
        senderId: msgObj.sender.id,
        messageId: msgObj.message.mid,
        text: text,
        phone: cleanPhone,
        hasPhone: Boolean(cleanPhone),
        receivedAt: new Date().toISOString()
      }
    }];
  }
}

return [];

