const geminiData = $input.first().json;
const candidate = geminiData.candidates && geminiData.candidates[0];
const part = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0];
let reply = part ? part.text : '';

if (!reply) {
  reply = 'வணக்கம் சார்! Danam Holdings Civil Engineering & Turnkey EPC 🏡. உங்கள் வீட்டுக் கனவிற்கான விபரங்களைப் பெற உங்கள் WhatsApp எண்ணைப் பகிருங்கள் சார், 2D பிளான் மற்றும் விலை விபரங்களை உடனே அனுப்புகிறோம்!';
}

const dmData = $('6. Route Event (Comment vs DM)').first().json;

return [{
  json: {
    ...dmData,
    replyText: reply.trim()
  }
}];

const item = $input.first().json;
const phone = item.phone || '';
const cleanDigits = phone.startsWith('91') ? phone : '91' + phone;

const text = item.text || '';
let area = 1200;
const centMatch = text.match(/(\d+(?:\.\d+)?)\s*(?:cent|சென்)/i);
if (centMatch) {
  area = Math.round(parseFloat(centMatch[1]) * 435.6 * 0.75 * 2);
}

const cementBags = Math.round(area * 0.42);
const steelTonnes = ((area * 3.8) / 1000).toFixed(2);
const bricks = Math.round(area * 18);

const minLakhs = ((area * 1850) / 100000).toFixed(2);
const maxLakhs = ((area * 2350) / 100000).toFixed(2);

const clientWelcome = `வணக்கம் சார்! 🏡✨\n` +
  `Danam Holdings Civil Engineering & Turnkey EPC, மதுரை.\n\n` +
  `நீங்கள் Instagram-ல் கேட்ட வீடு கட்டும் விபரங்கள் மற்றும் 2D Elevation தொகுப்பு:\n` +
  `• Standard Package: ₹1,850/sq.ft\n` +
  `• Premium Luxury Package: ₹2,250/sq.ft\n` +
  `• திட்ட மதிப்பீடு: ₹${minLakhs}L - ₹${maxLakhs}L (~${area} Sq.Ft)\n\n` +
  `எங்கள் தலைமை பொறியாளர் Er. Dhilip Kumar உங்களைத் தொடர்பு கொள்வார்.\n` +
  `முழு விபரங்களுக்கு: https://danamholdings.com`;

const engineerAlert = `🚨 *NEW INSTAGRAM LEAD CAPTURED!* 📸➔💬\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📱 *Phone:* +${cleanDigits}\n` +
  `📝 *Inquiry Text:* "${text}"\n` +
  `🧱 *BOQ Preview:* ~${cementBags} Cement bags | ${steelTonnes}T Steel | ~${bricks} Bricks\n` +
  `💰 *Est. Budget:* ₹${minLakhs}L - ₹${maxLakhs}L\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `👉 *Chat on WhatsApp:* https://wa.me/${cleanDigits}\n` +
  `👉 *Call Now:* tel:${cleanDigits}`;

return [{
  json: {
    ...item,
    customerPhone: cleanDigits,
    estimatedArea: area,
    minLakhs,
    maxLakhs,
    cementBags,
    steelTonnes,
    bricks,
    clientWelcomeMessage: clientWelcome,
    engineerAlertMessage: engineerAlert,
    processedAt: new Date().toISOString()
  }
}];
